-- FAQ per prodotto (generate dal principio attivo).
-- Aggiunge la colonna faqs e la popola per ogni prodotto Deus Medical.
-- Stesso contenuto del pulsante "Importa catalogo". Non tocca altro.

alter table public.products add column if not exists faqs jsonb not null default '[]'::jsonb;

update public.products set faqs='[{"q":"Come si presenta 3-TRENBOMED 150?","a":"3-TRENBOMED 150 è uno steroide androgeno-anabolizzante iniettabile (Steroide androgeno-anabolizzante) e contiene Trenbolone Hexahydrobenzylcarbonate / Enanthate / Acetate 50mg/ml. Si presenta in forma di Soluzione iniettabile con concentrazione 50 mg/ml, in confezione da 10 fiale / 1 mL — soluzione sterile I.M. È fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"Aromatizza?","a":"La tendenza ad aromatizzare, cioè a convertirsi in estrogeni tramite l''enzima aromatasi, è una proprietà chimica che dipende dalla molecola: ad esempio testosterone e boldenone aromatizzano, mentre nandrolone, trenbolone e drostanolone no o solo in misura trascurabile. Il principio attivo specifico è indicato in Trenbolone Hexahydrobenzylcarbonate / Enanthate / Acetate 50mg/ml."},{"q":"Cos''è l''estere e a cosa serve?","a":"Molti steroidi iniettabili sono esterificati (es. enantato, propionato, decanoato): l''estere ne modula la velocità di rilascio e l''emivita. Questa è una caratteristica chimica della molecola, non un''indicazione d''uso."},{"q":"Come si conserva?","a":"Conservare in luogo fresco e asciutto, al riparo dalla luce diretta. È normale che una soluzione oleosa possa addensarsi a basse temperature. Fare riferimento alle indicazioni sulla confezione."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}]'::jsonb, updated_at=now() where slug='3-trenbomed-150';
update public.products set faqs='[{"q":"Come si presenta DECAMED 250?","a":"DECAMED 250 è uno steroide androgeno-anabolizzante iniettabile (Steroide androgeno-anabolizzante) e contiene Nandrolone Decanoate 250mg/ml. Si presenta in forma di Soluzione iniettabile con concentrazione 250 mg/ml, in confezione da 10 fiale / 1 mL — soluzione sterile I.M. È fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"Aromatizza?","a":"La tendenza ad aromatizzare, cioè a convertirsi in estrogeni tramite l''enzima aromatasi, è una proprietà chimica che dipende dalla molecola: ad esempio testosterone e boldenone aromatizzano, mentre nandrolone, trenbolone e drostanolone no o solo in misura trascurabile. Il principio attivo specifico è indicato in Nandrolone Decanoate 250mg/ml."},{"q":"Cos''è l''estere e a cosa serve?","a":"Molti steroidi iniettabili sono esterificati (es. enantato, propionato, decanoato): l''estere ne modula la velocità di rilascio e l''emivita. Questa è una caratteristica chimica della molecola, non un''indicazione d''uso."},{"q":"Come si conserva?","a":"Conservare in luogo fresco e asciutto, al riparo dalla luce diretta. È normale che una soluzione oleosa possa addensarsi a basse temperature. Fare riferimento alle indicazioni sulla confezione."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}]'::jsonb, updated_at=now() where slug='decamed-250';
