update public.products set faqs='[{"q":"Cos''è un inibitore della PDE5?","a":"VIAMED 20 appartiene alla classe degli inibitori della fosfodiesterasi di tipo 5 (Inibitore PDE5), a cui appartengono tadalafil e sildenafil. Queste molecole inibiscono l''enzima PDE5. Il principio attivo è Sildenafil Citrate 20mg/tab, fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"Che differenza c''è tra tadalafil e sildenafil?","a":"Entrambi inibiscono la PDE5, ma differiscono per struttura chimica ed emivita: il tadalafil ha un''emivita più lunga rispetto al sildenafil. Il principio attivo specifico è indicato in Sildenafil Citrate 20mg/tab."},{"q":"In che forma è disponibile?","a":"È disponibile in forma di Compresse (uso orale) con concentrazione 20 mg/tab, in confezione da 50 compresse — uso orale."},{"q":"Come si conserva?","a":"Conservare in luogo fresco e asciutto, al riparo dalla luce e dall''umidità, come indicato sulla confezione."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}]'::jsonb, updated_at=now() where slug='viamed-20';
update public.products set faqs='[{"q":"Come si presenta WINIMED 10?","a":"WINIMED 10 è uno steroide androgeno-anabolizzante orale (Steroide androgeno-anabolizzante) e contiene Stanozolol 10mg/tab. Si presenta in forma di Compresse (uso orale) con concentrazione o dosaggio unitario 10 mg/tab, in confezione da 50 compresse — uso orale. È fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"Aromatizza?","a":"La tendenza ad aromatizzare è una proprietà chimica della molecola: tra gli orali, ad esempio, la methandienone aromatizza, mentre oxandrolone e stanozolol non aromatizzano. Il principio attivo specifico è indicato in Stanozolol 10mg/tab."},{"q":"Cosa significa che è 17-alfa-alchilato?","a":"Molti steroidi orali sono 17-alfa-alchilati, una modifica chimica che ne consente il passaggio per via orale resistendo al metabolismo epatico di primo passaggio. È una caratteristica strutturale della molecola, non un consiglio d''uso."},{"q":"Come si conserva?","a":"Conservare in luogo fresco e asciutto, al riparo dalla luce e dall''umidità, secondo le indicazioni sulla confezione."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}]'::jsonb, updated_at=now() where slug='winimed-10';
update public.products set faqs='[{"q":"Cos''è un agonista PPAR-delta?","a":"GW501516 10 appartiene alla classe degli agonisti del recettore PPARδ (Agonista PPARδ), a cui appartiene la cardarine (GW-501516). Queste molecole attivano il recettore nucleare PPARδ. Il principio attivo è Cardarine (GW-501516) 10mg/tab, fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"La cardarine è un SARM?","a":"No. Nonostante venga spesso associata ai SARM nella comunicazione commerciale, la cardarine è un agonista PPARδ e non interagisce con il recettore androgeno. Sono classi farmacologiche diverse."},{"q":"In che forma è disponibile?","a":"È disponibile in forma di Compresse (uso orale) con concentrazione 10 mg/tab, in confezione da 50 compresse — uso orale."},{"q":"Come si conserva?","a":"Conservare in luogo fresco e asciutto, al riparo dalla luce diretta e dall''umidità, come indicato sulla confezione."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}]'::jsonb, updated_at=now() where slug='gw501516-10';
update public.products set faqs='[{"q":"Cos''è un SARM?","a":"LGD4033 10 appartiene alla classe dei modulatori selettivi del recettore androgeno (SARM), a cui appartengono ostarine, ligandrol e RAD-140. Queste molecole interagiscono in modo selettivo con il recettore androgeno. Il principio attivo è Ligandrol (LGD-4033) 10mg/tab, fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"Un SARM è uno steroide?","a":"No. I SARM agiscono sullo stesso recettore androgeno ma hanno struttura non steroidea e un profilo di selettività differente rispetto agli steroidi androgeno-anabolizzanti. Sono classi distinte."},{"q":"In che forma è disponibile?","a":"È disponibile in forma di Compresse (uso orale) con concentrazione 10 mg/tab, in confezione da 50 compresse — uso orale."},{"q":"Fornite indicazioni su come assumerlo?","a":"Le informazioni disponibili riguardano composizione, classe e meccanismo e sono di natura fattuale, non un protocollo o un consiglio medico. Il prodotto è destinato esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}]'::jsonb, updated_at=now() where slug='lgd4033-10';
update public.products set faqs='[{"q":"Cos''è un SARM?","a":"MK2866 10 appartiene alla classe dei modulatori selettivi del recettore androgeno (SARM), a cui appartengono ostarine, ligandrol e RAD-140. Queste molecole interagiscono in modo selettivo con il recettore androgeno. Il principio attivo è Ostarine (MK-2866) 10mg/tab, fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"Un SARM è uno steroide?","a":"No. I SARM agiscono sullo stesso recettore androgeno ma hanno struttura non steroidea e un profilo di selettività differente rispetto agli steroidi androgeno-anabolizzanti. Sono classi distinte."},{"q":"In che forma è disponibile?","a":"È disponibile in forma di Compresse (uso orale) con concentrazione 10 mg/tab, in confezione da 50 compresse — uso orale."},{"q":"Fornite indicazioni su come assumerlo?","a":"Le informazioni disponibili riguardano composizione, classe e meccanismo e sono di natura fattuale, non un protocollo o un consiglio medico. Il prodotto è destinato esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}]'::jsonb, updated_at=now() where slug='mk2866-10';
update public.products set faqs='[{"q":"Cos''è un secretagogo del GH?","a":"MK677 10 appartiene alla classe dei secretagoghi dell''ormone della crescita (Secretagogo GH), a cui appartiene l''ibutamoren (MK-677). Queste molecole stimolano il recettore della grelina favorendo la secrezione endogena di GH. Il principio attivo è Ibutamoren (MK-677) 10mg/tab, fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"Un secretagogo è la stessa cosa dell''ormone della crescita?","a":"No. L''ormone della crescita è la somatropina somministrata direttamente, mentre un secretagogo come l''MK-677 agisce sul recettore della grelina stimolando la produzione endogena di GH. Sono due categorie distinte."},{"q":"In che forma è disponibile?","a":"È disponibile in forma di Compresse (uso orale) con concentrazione 10 mg/tab, in confezione da 50 compresse — uso orale."},{"q":"Come si conserva?","a":"Conservare in luogo fresco e asciutto, al riparo dalla luce e dall''umidità, secondo le indicazioni sulla confezione."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}]'::jsonb, updated_at=now() where slug='mk677-10';
