update public.products set faqs='[{"q":"Cosa contiene questo peptide?","a":"BPC 157 contiene BPC-157 Pentadecapeptide 5mg/vial e appartiene alla classe dei peptidi di sintesi (Peptide), categoria che comprende molecole come BPC-157, TB-500, ipamorelin e melanotan. È fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"In che forma viene fornito?","a":"Viene fornito tipicamente come Flaconcino liofilizzato con titolo 5 mg, in confezione da 1 flaconcino. La forma liofilizzata richiede ricostituzione prima dell''analisi."},{"q":"I peptidi hanno tutti lo stesso meccanismo?","a":"No. Sotto la definizione di peptidi di sintesi rientrano molecole con bersagli molto diversi tra loro. Il meccanismo dipende dal peptide specifico indicato in BPC-157 Pentadecapeptide 5mg/vial."},{"q":"Come si conserva?","a":"Il prodotto liofilizzato si conserva in luogo fresco o refrigerato; una volta ricostituito richiede in genere refrigerazione. Fare riferimento alle indicazioni sulla confezione."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}]'::jsonb, updated_at=now() where slug='bpc-157';
update public.products set faqs='[{"q":"Cosa contiene questo peptide?","a":"CJC-1295 DAC contiene CJC-1295 DAC 2mg/vial e appartiene alla classe dei peptidi di sintesi (Peptide), categoria che comprende molecole come BPC-157, TB-500, ipamorelin e melanotan. È fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"In che forma viene fornito?","a":"Viene fornito tipicamente come Flaconcino liofilizzato con titolo 2 mg, in confezione da 1 flaconcino. La forma liofilizzata richiede ricostituzione prima dell''analisi."},{"q":"I peptidi hanno tutti lo stesso meccanismo?","a":"No. Sotto la definizione di peptidi di sintesi rientrano molecole con bersagli molto diversi tra loro. Il meccanismo dipende dal peptide specifico indicato in CJC-1295 DAC 2mg/vial."},{"q":"Come si conserva?","a":"Il prodotto liofilizzato si conserva in luogo fresco o refrigerato; una volta ricostituito richiede in genere refrigerazione. Fare riferimento alle indicazioni sulla confezione."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}]'::jsonb, updated_at=now() where slug='cjc-1295-dac';
update public.products set faqs='[{"q":"Cos''è l''ormone della crescita?","a":"DEUSTROPIN 4/12 contiene Somatropina (hGH ricombinante) 4mg (12IU)/vial, ovvero somatropina, la forma ricombinante dell''ormone della crescita umano; appartiene alla classe Ormone della crescita (somatropina). È fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"In che forma viene fornito?","a":"Viene fornito generalmente come Flaconcino liofilizzato con titolo 4 mg, in confezione da 10 flaconcini / 4 mg (12IU). La forma liofilizzata richiede ricostituzione prima dell''analisi."},{"q":"Come si misura la somatropina?","a":"Il contenuto di somatropina viene espresso in unità internazionali (UI) o in milligrammi. Il titolo specifico di questo prodotto è riportato in 4 mg."},{"q":"Come si conserva?","a":"Il prodotto liofilizzato si conserva in genere refrigerato; una volta ricostituito va mantenuto in frigorifero. Fare sempre riferimento alle indicazioni sulla confezione."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}]'::jsonb, updated_at=now() where slug='deustropin-4-12';
