update public.products set faqs='[{"q":"Cosa contiene questo peptide?","a":"GHK-CU contiene GHK-Cu Copper Tripeptide-1 50mg/vial e appartiene alla classe dei peptidi di sintesi (Peptide), categoria che comprende molecole come BPC-157, TB-500, ipamorelin e melanotan. È fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"In che forma viene fornito?","a":"Viene fornito tipicamente come Flaconcino liofilizzato con titolo 50 mg, in confezione da 1 flaconcino. La forma liofilizzata richiede ricostituzione prima dell''analisi."},{"q":"I peptidi hanno tutti lo stesso meccanismo?","a":"No. Sotto la definizione di peptidi di sintesi rientrano molecole con bersagli molto diversi tra loro. Il meccanismo dipende dal peptide specifico indicato in GHK-Cu Copper Tripeptide-1 50mg/vial."},{"q":"Come si conserva?","a":"Il prodotto liofilizzato si conserva in luogo fresco o refrigerato; una volta ricostituito richiede in genere refrigerazione. Fare riferimento alle indicazioni sulla confezione."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}]'::jsonb, updated_at=now() where slug='ghk-cu';
update public.products set faqs='[{"q":"Cos''è l''ormone della crescita?","a":"GHRP-2 contiene Growth Hormone-Releasing Peptide 2 10mg/vial, ovvero somatropina, la forma ricombinante dell''ormone della crescita umano; appartiene alla classe Ormone della crescita (somatropina). È fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"In che forma viene fornito?","a":"Viene fornito generalmente come Flaconcino liofilizzato con titolo 10 mg, in confezione da 1 flaconcino. La forma liofilizzata richiede ricostituzione prima dell''analisi."},{"q":"Come si misura la somatropina?","a":"Il contenuto di somatropina viene espresso in unità internazionali (UI) o in milligrammi. Il titolo specifico di questo prodotto è riportato in 10 mg."},{"q":"Come si conserva?","a":"Il prodotto liofilizzato si conserva in genere refrigerato; una volta ricostituito va mantenuto in frigorifero. Fare sempre riferimento alle indicazioni sulla confezione."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}]'::jsonb, updated_at=now() where slug='ghrp-2';
