update public.products set faqs='[{"q":"Cos''è un inibitore della PDE5?","a":"VIAMED 100 appartiene alla classe degli inibitori della fosfodiesterasi di tipo 5 (Inibitore PDE5), a cui appartengono tadalafil e sildenafil. Queste molecole inibiscono l''enzima PDE5. Il principio attivo è Sildenafil 100mg, fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"Che differenza c''è tra tadalafil e sildenafil?","a":"Entrambi inibiscono la PDE5, ma differiscono per struttura chimica ed emivita: il tadalafil ha un''emivita più lunga rispetto al sildenafil. Il principio attivo specifico è indicato in Sildenafil 100mg."},{"q":"In che forma è disponibile?","a":"È disponibile in forma di Compresse (uso orale) con concentrazione 100 mg, in confezione da 7 bustine / 100 mg — uso orale."},{"q":"Come si conserva?","a":"Conservare in luogo fresco e asciutto, al riparo dalla luce e dall''umidità, come indicato sulla confezione."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}]'::jsonb, updated_at=now() where slug='viamed-100';
